import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {VersionedTransaction} from '@solana/web3.js';
import {createPactClient,isLicenseStatusFresh,PACT_PROGRAM_ID,DEVNET_GENESIS} from '../dist/index.js';
import {createCheckoutClient,validateCheckoutMetadata} from '../dist/checkout.js';
import {createPlatformReader} from '../dist/server.js';

// These expected bytes/addresses were generated by solders, Python struct and
// Foundry cast, not by web3.js, Noble or the implementations under test.
const golden=JSON.parse(readFileSync(new URL('./golden/protocol-v1.json',import.meta.url),'utf8'));
const system='11111111111111111111111111111111',clock='SysvarC1ock11111111111111111111111111111111';
const sysvar='Sysvar1111111111111111111111111111111111111',loader='BPFLoaderUpgradeab1e11111111111111111111111';
const rpcUrl='https://golden.invalid';
const raw=(hex,owner=golden.program)=>({owner,executable:false,lamports:1000000,data:[Buffer.from(hex,'hex').toString('base64'),'base64']});

function rpcFixture(vector,{license='active',offerMissing=false,mutate=()=>{},genesis=golden.genesis}={}){
  const calls=[];
  const fetch=async(_url,init)=>{
    const request=JSON.parse(init.body);calls.push(request);
    let result;
    if(request.method==='getGenesisHash')result=genesis;
    else if(request.method==='getLatestBlockhash')result={context:{slot:100},value:{blockhash:golden.blockhash,lastValidBlockHeight:golden.lastValidBlockHeight}};
    else if(request.method==='getMultipleAccounts'){
      result={context:{slot:golden.clock.slot},value:request.params[0].map(address=>{
        if(address===vector.offer)return offerMissing?null:raw(vector.offerDataHex);
        if(address===vector.license)return license==='missing'?null:license==='prefunded'?raw('',system):raw(vector.licenseDataHex[license]);
        if(address===clock)return raw(golden.clock.dataHex,sysvar);
        if(address===golden.program)return{owner:loader,executable:true,lamports:1000000,data:['','base64']};
        return null;
      })};
      mutate(result,request);
    }else assert.fail(`Forbidden fixture method: ${request.method}`);
    return Response.json({jsonrpc:'2.0',id:request.id,result});
  };
  return{fetch,calls};
}
function adapter(){return{connect:async()=>golden.buyer,disconnect:async()=>{},getPublicKey:()=>golden.buyer,
  signTransaction:async()=>assert.fail('Golden preparation never signs'),subscribe:()=>()=>{},destroy(){}};}
function changeBytes(snapshot,index,fn){const bytes=Buffer.from(snapshot.value[index].data[0],'base64');fn(bytes);snapshot.value[index].data[0]=bytes.toString('base64');}
function transactionSemantics(base64){
  const transaction=VersionedTransaction.deserialize(Buffer.from(base64,'base64')),message=transaction.message;
  const keys=message.staticAccountKeys.map(key=>key.toBase58());
  const privilege=index=>({address:keys[index],signer:message.isAccountSigner(index),writable:message.isAccountWritable(index)});
  return{version:message.version,payer:keys[0],header:message.header,blockhash:message.recentBlockhash,
    signatures:transaction.signatures.map(signature=>Buffer.from(signature).toString('hex')),
    lookupTables:message.addressTableLookups,
    staticKeys:keys.map((_key,index)=>privilege(index)).sort((a,b)=>a.address.localeCompare(b.address)),
    instructions:message.compiledInstructions.map(instruction=>({program:keys[instruction.programIdIndex],
      dataHex:Buffer.from(instruction.data).toString('hex'),accounts:Array.from(instruction.accountKeyIndexes,privilege)}))};
}
function assertIndependentTransaction(actual,expected){
  // Rust and web3.js choose different valid static-key ordering. Compare the
  // complete resolved message, including privileges and all unused-key exposure.
  assert.deepEqual(transactionSemantics(actual),transactionSemantics(expected));
}

test('reviewed program/network and wire-spec discriminators match independent vectors',()=>{
  assert.equal(PACT_PROGRAM_ID,golden.program);assert.equal(DEVNET_GENESIS,golden.genesis);
  const wire=JSON.parse(readFileSync(new URL('../../../solana/wire-spec.json',import.meta.url),'utf8'));
  for(const v of golden.vectors){
    assert.equal(v.instructions.create.dataHex.slice(0,16),wire.instructions.createOffer.discriminatorHex);
    assert.equal(v.instructions.buy.dataHex,wire.instructions.buyLicense.discriminatorHex);
    assert.equal(v.instructions.deactivate.dataHex,wire.instructions.deactivateOffer.discriminatorHex);
    assert.equal(v.offerDataHex.length/2,wire.accounts.offer.size);
    assert.equal(v.licenseDataHex.active.length/2,wire.accounts.license.size);
  }
});

for(const vector of golden.vectors){
  test(`${vector.name}: independent PDA/account/integer and exact metadata vectors`,async()=>{
    const fixture=rpcFixture(vector),now=()=>0;
    const status=await createPactClient({rpcUrl,fetch:fixture.fetch,now}).getLicenseStatus({offer:vector.offer,wallet:golden.buyer});
    assert.equal(status.licensePda,vector.license);assert.equal(status.active,true);assert.equal(status.expiry,'1060');
    assert.equal(status.contextSlot,golden.clock.slot);assert.equal(status.chainTimestamp,golden.clock.timestamp);
    const checkout=createCheckoutClient({programId:golden.program,rpcUrl,fetch:fixture.fetch,now,walletAdapter:adapter()});
    try{
      const quote=await checkout.getOffer({offer:vector.offer});
      assert.equal(quote.seller,golden.seller);assert.equal(quote.priceLamports,vector.priceLamports);
      assert.equal(quote.durationSeconds,vector.durationSeconds);assert.equal(quote.termsHash,vector.metadataKeccak256);
      assert.equal(Buffer.from(vector.metadataJson).toString('hex'),vector.metadataUtf8Hex);
      const metadata=JSON.parse(vector.metadataJson);
      assert.deepEqual(validateCheckoutMetadata(vector.metadataJson,quote),{title:metadata.title,terms:metadata.terms});
      assert.throws(()=>validateCheckoutMetadata(vector.metadataJson+' ',quote));
      assert.deepEqual(validateCheckoutMetadata(vector.metadataJson+' ',{...quote,termsHash:vector.metadataWithTrailingSpaceKeccak256}),{title:metadata.title,terms:metadata.terms});
    }finally{checkout.destroy();}
  });
  test(`${vector.name}: unsigned purchase and offer match independent Rust compiler`,async()=>{
    const fixture=rpcFixture(vector,{license:'missing'}),now=()=>0;
    const checkout=createCheckoutClient({programId:golden.program,rpcUrl,fetch:fixture.fetch,now,walletAdapter:adapter()});
    try{
      const prepared=await checkout.preparePurchase({offer:vector.offer,metadataJson:vector.metadataJson});
      assertIndependentTransaction(Buffer.from(prepared.transaction.serialize()).toString('base64'),vector.unsignedBuyBase64);
      assert.equal(prepared.lastValidBlockHeight,golden.lastValidBlockHeight);
    }finally{checkout.destroy();}
    const prepared=await createPlatformReader({rpcUrl,fetch:fixture.fetch,now}).prepareCheckout({network:'devnet',offerAddress:vector.offer,walletAddress:golden.buyer,metadataJson:vector.metadataJson});
    assertIndependentTransaction(prepared.transactionBase64,vector.unsignedBuyBase64);assert.equal(prepared.licensePda,vector.license);
    const creation=rpcFixture(vector,{offerMissing:true});
    const offer=await createPlatformReader({rpcUrl,fetch:creation.fetch,now}).prepareOffer({network:'devnet',sellerWallet:golden.seller,nonce:vector.nonce,metadataJson:vector.metadataJson});
    assert.equal(offer.offer,vector.offer);assert.equal(offer.termsHash,vector.metadataKeccak256);
    assertIndependentTransaction(offer.transactionBase64,vector.unsignedCreateBase64);
  });
}

for(const [state,active,expiry]of[['active',true,'1060'],['equal',false,'1000'],['expired',false,'999'],['maximum',true,'9223372036854775807'],['missing',false,'0'],['prefunded',false,'0']]){
  test(`entitlement expiry boundary ${state} preserves exact signed integer semantics`,async()=>{
    const v=golden.vectors[0],fixture=rpcFixture(v,{license:state});
    const status=await createPactClient({rpcUrl,fetch:fixture.fetch,now:()=>0}).getLicenseStatus({offer:v.offer,wallet:golden.buyer});
    assert.equal(status.active,active);assert.equal(status.expiry,expiry);
    assert.equal(status.state,active?'active':state==='missing'||state==='prefunded'?'missing':'expired');
  });
}

const corruptions=[
  ['offer owner',s=>{s.value[0].owner=system;}],
  ['offer executable',s=>{s.value[0].executable=true;}],
  ['offer length',s=>{s.value[0].data[0]=Buffer.from(golden.vectors[0].offerDataHex,'hex').subarray(1).toString('base64');}],
  ['offer discriminator',s=>changeBytes(s,0,b=>{b[0]^=1;})],
  ['offer bump',s=>changeBytes(s,0,b=>{b[97]^=1;})],
  ['offer active boolean',s=>changeBytes(s,0,b=>{b[96]=2;})],
  ['zero price',s=>changeBytes(s,0,b=>b.writeBigUInt64LE(0n,48))],
  ['duration overflow',s=>changeBytes(s,0,b=>b.writeBigUInt64LE(31536001n,56))],
  ['zero terms commitment',s=>changeBytes(s,0,b=>b.fill(0,64,96))],
  ['license owner',s=>{s.value[1].owner=sysvar;}],
  ['license discriminator',s=>changeBytes(s,1,b=>{b[0]^=1;})],
  ['license embedded offer',s=>changeBytes(s,1,b=>{b[8]^=1;})],
  ['license embedded buyer',s=>changeBytes(s,1,b=>{b[40]^=1;})],
  ['license bump',s=>changeBytes(s,1,b=>{b[80]^=1;})],
  ['negative expiry',s=>changeBytes(s,1,b=>b.writeBigInt64LE(-1n,72))],
  ['Clock context mismatch',s=>changeBytes(s,2,b=>b.writeBigUInt64LE(99n,0))],
  ['negative chain timestamp',s=>changeBytes(s,2,b=>b.writeBigInt64LE(-1n,32))],
  ['program not executable',s=>{s.value[3].executable=false;}],
  ['wrong program loader',s=>{s.value[3].owner=system;}],
];
for(const [name,mutate]of corruptions){
  test(`independent account fixture rejects ${name}`,async()=>{
    const v=golden.vectors[0],fixture=rpcFixture(v,{mutate});
    await assert.rejects(createPactClient({rpcUrl,fetch:fixture.fetch,now:()=>0}).getLicenseStatus({offer:v.offer,wallet:golden.buyer}),error=>['INVALID_ACCOUNT','STALE'].includes(error.code));
  });
}

test('wrong network and substituted offer identity fail closed',async()=>{
  const v=golden.vectors[0],wrong=rpcFixture(v,{genesis:'not-devnet'});
  await assert.rejects(createPactClient({rpcUrl,fetch:wrong.fetch,now:()=>0}).getLicenseStatus({offer:v.offer,wallet:golden.buyer}),e=>e.code==='WRONG_NETWORK');
  const fixture=rpcFixture(v,{mutate:s=>{s.value[0]=raw(v.offerDataHex);}});
  await assert.rejects(createPactClient({rpcUrl,fetch:fixture.fetch,now:()=>0}).getLicenseStatus({offer:golden.seller,wallet:golden.buyer}),e=>e.code==='INVALID_ACCOUNT');
});

test('exact 64 KiB UTF-8 metadata accepted; one further byte refused',()=>{
  const boundary=golden.metadataBoundary;
  const json=JSON.stringify({...boundary.base,terms:boundary.fillCharacter.repeat(boundary.fillCount)+boundary.asciiSuffix});
  assert.equal(Buffer.byteLength(json),boundary.utf8Bytes);
  const quote={priceLamports:'1',durationSeconds:'1',termsHash:boundary.keccak256};
  assert.equal(validateCheckoutMetadata(json,quote).title,boundary.base.title);
  assert.throws(()=>validateCheckoutMetadata(json+' ',quote));
});

test('server creation rejects unsigned integer and duration boundaries outside protocol',async()=>{
  const v=golden.vectors[0],fixture=rpcFixture(v,{offerMissing:true}),reader=createPlatformReader({rpcUrl,fetch:fixture.fetch,now:()=>0});
  for(const nonce of['-1','18446744073709551616','01'])await assert.rejects(async()=>reader.prepareOffer({network:'devnet',sellerWallet:golden.seller,nonce,metadataJson:v.metadataJson}),e=>e.code==='INVALID_INPUT');
  for(const changes of[{priceLamports:'0'},{priceLamports:'18446744073709551616'},{durationSeconds:'0'},{durationSeconds:'31536001'}]){
    const metadataJson=JSON.stringify({...JSON.parse(v.metadataJson),...changes});
    await assert.rejects(async()=>reader.prepareOffer({network:'devnet',sellerWallet:golden.seller,nonce:'1',metadataJson}),e=>e.code==='INVALID_INPUT');
  }
  assert.equal(fixture.calls.length,0,'Invalid terms never reach RPC');
});

test('freshness endpoints are strict and stalled provider history survives reads',async()=>{
  const v=golden.vectors[0],fixture=rpcFixture(v);let now=0;
  const client=createPactClient({rpcUrl,fetch:fixture.fetch,now:()=>now});
  const status=await client.getLicenseStatus({offer:v.offer,wallet:golden.buyer});
  assert.equal(isLicenseStatusFresh(status,7999),true);assert.equal(isLicenseStatusFresh(status,8000),false);
  assert.equal(isLicenseStatusFresh(status,-1),false);
  assert.equal(isLicenseStatusFresh({...status,expiry:'1001'},999),true);
  assert.equal(isLicenseStatusFresh({...status,expiry:'1001'},1000),false);
  now=11999;assert.equal((await client.getLicenseStatus({offer:v.offer,wallet:golden.buyer})).active,true);
  now=12000;await assert.rejects(client.getLicenseStatus({offer:v.offer,wallet:golden.buyer}),e=>e.code==='STALE');
});
